CREATE TABLE customers(id INTEGER PRIMARY KEY, name VARCHAR(80) NOT NULL, city VARCHAR(80));
CREATE TABLE products(id INTEGER PRIMARY KEY, name VARCHAR(80) NOT NULL, category VARCHAR(30) NOT NULL, price NUMERIC(10,2) NOT NULL CHECK(price>=0), stock INTEGER NOT NULL CHECK(stock>=0), active BOOLEAN NOT NULL);
CREATE TABLE orders(id INTEGER PRIMARY KEY, customer_id INTEGER REFERENCES customers(id), status VARCHAR(30) NOT NULL, placed_on DATE NOT NULL);
CREATE TABLE order_items(order_id INTEGER REFERENCES orders(id), product_id INTEGER REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity>0), PRIMARY KEY(order_id,product_id));
CREATE TABLE archived_orders(id INTEGER PRIMARY KEY, customer_id INTEGER, status VARCHAR(30) NOT NULL);
CREATE TABLE audit_log(id INTEGER PRIMARY KEY, event VARCHAR(40) NOT NULL);
CREATE TABLE scratch_flags(id INTEGER PRIMARY KEY, priority VARCHAR(20) NOT NULL, raised_on DATE NOT NULL);
CREATE TABLE temp_import(id INTEGER PRIMARY KEY);
CREATE TABLE unused_import(id INTEGER PRIMARY KEY);
CREATE TABLE preview_numbers(amount INTEGER);
CREATE VIEW obsolete_report AS SELECT id, name FROM products;
CREATE VIEW active_catalog AS SELECT id, name FROM products WHERE active;
